// POST /api/analyse — receive photos, return AI analysis
app.post('/api/analyse', upload.array('photos', 10), async (req, res) => {
  try {
    const { sectionId } = req.body;

    if (!sectionId || !SECTION_PROMPTS[sectionId]) {
      return res.status(400).json({ error: 'Invalid section ID' });
    }

    if (!req.files || req.files.length === 0) {
      return res.status(400).json({ error: 'No photos uploaded' });
    }

    // Resize images server-side to stay under 5MB API limit
    const imageBlocks = await Promise.all(req.files.map(async file => {
      try {
        const img = await Jimp.read(file.buffer);
        // Scale down if wider/taller than 1600px
        if (img.width > 1600 || img.height > 1600) {
          img.scaleToFit({ w: 1600, h: 1600 });
        }
        // Export as JPEG at 80% quality
        img.quality = 80;
        const resized = await img.getBuffer(JimpMime.jpeg);
        return {
          type: 'image',
          source: { type: 'base64', media_type: 'image/jpeg', data: resized.toString('base64') }
        };
      } catch (e) {
        // Fallback: use original but warn
        console.warn('Could not resize image:', e.message);
        return {
          type: 'image',
          source: { type: 'base64', media_type: file.mimetype || 'image/jpeg', data: file.buffer.toString('base64') }
        };
      }
    }));

    const client = getClient();
    const response = await client.messages.create({
      model: 'claude-opus-4-5',
      max_tokens: 1024,
      messages: [{
        role: 'user',
        content: [
          ...imageBlocks,
          { type: 'text', text: SECTION_PROMPTS[sectionId] }
        ]
      }]
    });

    const text = response.content.map(c => c.text || '').join('');

    // Parse JSON from response
    let result;
    try {
      // Strip any markdown fences if present
      const clean = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
      result = JSON.parse(clean);
    } catch (e) {
      // If JSON parse fails, return raw text
      result = {
        status: 'Requires Further Investigation',
        observations: text,
        actions: 'Please review the analysis above manually.',
        timescale: '1 month'
      };
    }

    res.json({ success: true, result });

  } catch (err) {
    console.error('Analysis error full:', err);
    const msg = err?.error?.message || err?.message || JSON.stringify(err) || 'Analysis failed';
    res.status(500).json({ error: msg, stack: err?.stack?.split('\n')[0] });
  }
});

// POST /api/summary — generate executive summary from all section data
app.post('/api/summary', express.json(), async (req, res) => {
  try {
    const { property, sections, riskRating } = req.body;

    const sectionText = sections.map(s =>
      `## ${s.name}\nStatus: ${s.status || 'Not assessed'}\nObservations: ${s.observations || 'None'}\nActions: ${s.actions || 'None'}`
    ).join('\n\n---\n\n');

    const prompt = `You are a fire risk assessor. Based on the following survey findings, write a concise professional executive summary for a PAS 79-2:2020 Fire Risk Assessment report.

Property: ${property.address}
Assessor: ${property.assessor}
Date: ${property.date}
Responsible Person: ${property.rp}
Flats: ${property.flats} | Floors: ${property.floors} | Max Occupancy: ${property.occ}
Construction: ${property.construction}
Overall Risk Rating: ${riskRating || 'Not specified'}

SECTION FINDINGS:
${sectionText}

Write 2-3 paragraphs covering: overall fire safety status, key deficiencies found, and general recommendations. Use formal FRA report language. Do not use markdown formatting - plain paragraphs only.`;

    const client = getClient();
    const response = await client.messages.create({
      model: 'claude-opus-4-5',
      max_tokens: 600,
      messages: [{ role: 'user', content: prompt }]
    });

    const summary = response.content.map(c => c.text || '').join('');
    res.json({ success: true, summary });

  } catch (err) {
    console.error('Summary error:', err);
    res.status(500).json({ error: err.message || 'Summary generation failed' });
  }
});

// Key check endpoint — visit /api/keycheck to verify API key is set
app.get('/api/keycheck', (req, res) => {
  const key = process.env.ANTHROPIC_API_KEY;
  if (!key) return res.json({ ok: false, message: 'ANTHROPIC_API_KEY is NOT set' });
  res.json({ ok: true, message: `Key found — starts with: ${key.substring(0, 12)}...` });
});

app.listen(PORT, () => {
  const key = process.env.ANTHROPIC_API_KEY;
  console.log(`Energise FRA App running on port ${PORT}`);
  console.log(`API key status: ${key ? 'SET (starts with ' + key.substring(0, 12) + '...)' : 'NOT SET — add ANTHROPIC_API_KEY in Railway Variables'}`);
});
